/* Opsentia — data-connected seven-screen desktop UI. No CDN or framework required.
   Synthetic fixtures are not verified live operational events or real notification delivery. */
const state={page:'live',queue:'Queue A',asOf:'2026-09-13 17:00:00',data:null,dialog:null,search:'',loading:false,metricsHorizon:'intraday',chatOpen:false,chatMessages:[{sender:'assistant',text:'Welcome to **Opsentia Chat**. Ask about real-time metrics, full-day EOD performance projections, period comparisons, or enterprise SOP playbooks.'}],chatLoading:false,chatInput:''};
const pages=[['live','Live Intelligence','radar'],['metrics','All Metrics','chart'],['investigation','Investigation','search'],['decision','Decision Lab','grid'],['actions','Actions & Approvals','check'],['notifications','Notifications','bell'],['historical','Historical Analytics','history']];
const colors={blue:'#338eff',cyan:'#2cdded',violet:'#b463f5',red:'#ff587b',amber:'#fbbd5c',green:'#13dca9',mute:'#6889b0'};
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,d=0)=>v===null||v===undefined||Number.isNaN(+v)?'—':Number(v).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const percent=(v,d=1)=>v==null?'—':n(v*100,d)+'%';
const compact=v=>v==null?'—':Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:1}).format(v);
const hh=t=>String(t||'').slice(11,16), day=t=>String(t||'').slice(0,10);
const at=()=>state.data?.meta?.as_of||state.asOf;
const isRed=x=>x&&(['CRITICAL','HIGH'].includes(String(x).toUpperCase()));
function icon(name,size=18){let p={radar:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="3"/><path d="M12 3v5M12 16v5M3 12h5M16 12h5"/>',chart:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 16v-5m5 5V7m5 9v-3"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',check:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 6-6"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',history:'<path d="M3 11a9 9 0 1 1 2.8 6.6M3 4v7h7M12 7v5l4 3"/>',bolt:'<path d="m13 2-9 11h7l-1 9 10-12h-7z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>',file:'<path d="M6 2h8l5 5v15H6zM14 2v6h5M9 13h7m-7 4h7"/>',spark:'<path d="m12 2 2.5 6.5L21 11l-6.5 2.5L12 20l-2.5-6.5L3 11l6.5-2.5z"/>',filter:'<path d="M3 4h18l-7 8v8l-4-2v-6z"/>',alert:'<path d="m12 2 10 19H2zM12 8v6m0 4h.01"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',shield:'<path d="m12 2 8 4v6c0 5-3 8-8 10-5-2-8-5-8-10V6z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4m8-4v4"/>'}[name]||'<circle cx="12" cy="12" r="8"/>';return `<svg class="nav-svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p}</svg>`}
function spark(vals,color=colors.blue){vals=(vals||[]).filter(v=>Number.isFinite(+v)).map(Number);if(vals.length<2)return '';let mi=Math.min(...vals),ma=Math.max(...vals),h=30,w=54;let xy=vals.map((v,i)=>`${i*w/(vals.length-1)},${h-3-(v-mi)/(ma-mi||1)*(h-7)}`).join(' ');return `<svg class="spark" viewBox="0 0 ${w} ${h}"><polyline points="${xy}" fill="none" stroke="${color}" stroke-width="1.9" stroke-linejoin="round" stroke-linecap="round"/></svg>`}
let chartIdx=0;
function plot({title='',points=[],lines=[],target=null,targetLabel='',height=232,min=null,max=null,footer='',xLabels=7}){
  const W=810,H=height,pad={top:15,right:19,bottom:32,left:41},plotW=W-pad.left-pad.right,plotH=H-pad.top-pad.bottom;
  const valid=lines.flatMap(l=>(l.values||[]).filter(v=>v!==null&&Number.isFinite(+v)).map(Number));if(target!==null)valid.push(target);
  const minData=min!=null?min:Math.floor((Math.min(...valid,0)*.92)/10)*10,maxData=max!=null?max:Math.ceil((Math.max(...valid,1)*1.05)/10)*10;
  const lo=Number.isFinite(minData)?minData:0,hi=maxData>lo?maxData:lo+1;
  const x=i=>pad.left+i/(Math.max(points.length-1,1))*plotW;
  const y=v=>pad.top+(hi-Number(v))/(hi-lo)*plotH;
  const tks=[0,.25,.5,.75,1].map(f=>{const v=lo+(hi-lo)*f,Y=y(v);return `<line x1="${pad.left}" y1="${Y}" x2="${W-pad.right}" y2="${Y}" stroke="#193b5a" stroke-dasharray="3 4"/><text x="${pad.left-8}" y="${Y+4}" fill="#8fa9c5" font-size="11" text-anchor="end">${n(v,0)}</text>`}).join('');
  const every=Math.max(1,Math.ceil(points.length/Math.max(2,xLabels)));let labels=points.map((p,i)=>(i%every===0||i===points.length-1)?`<text x="${x(i)}" y="${H-7}" fill="#87a9c6" font-size="10" text-anchor="middle">${esc(p)}</text>`:'').join('');
  const id='f'+chartIdx++;
  let targetLine=target===null?'':`<line x1="${pad.left}" x2="${W-pad.right}" y1="${y(target)}" y2="${y(target)}" stroke="${colors.green}" stroke-width="1.5" stroke-dasharray="7 5"/>`;
  let paths=lines.map((l,k)=>{
     const vals=l.values||[];let segments=[],current=[];
     vals.forEach((v,i)=>{if(v==null||!Number.isFinite(+v)){if(current.length){segments.push(current);current=[]}}else current.push([x(i),y(v)])});if(current.length)segments.push(current);
     return segments.map((seg,si)=>{let d=seg.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ');
       let fill=l.fill&&seg.length>2?`<path d="${d} L${seg.at(-1)[0]} ${y(lo)} L${seg[0][0]} ${y(lo)}Z" fill="url(#${id}_${k})" opacity=".65"/>`:'';
       return fill+`<path d="${d}" fill="none" stroke="${l.color||colors.blue}" stroke-width="${l.width||2.4}" stroke-linecap="round" stroke-linejoin="round" ${l.dashed?'stroke-dasharray="6 5"':''}/>`
     }).join('');
  }).join('');
  const legend=lines.map(l=>`<span><i class="dot" style="background:${l.color}"></i>${esc(l.label||l.key)}</span>`).join('')+(target!==null?`<span><i class="dot" style="background:${colors.green}"></i>${esc(targetLabel||'Target')}</span>`:'');
  return `<div class="panel-head"><h2>${esc(title)}</h2><div class="legend">${legend}</div></div><svg role="img" aria-label="${esc(title)}" class="chart-svg" viewBox="0 0 ${W} ${H}"><defs>${lines.map((l,k)=>`<linearGradient id="${id}_${k}" x1="0" x2="0" y1="0" y2="1"><stop stop-color="${l.color}" stop-opacity=".32"/><stop offset="1" stop-color="${l.color}" stop-opacity="0"/></linearGradient>`).join('')}</defs>${tks}${targetLine}${paths}${labels}</svg>${footer?`<div class="panel-footer">${esc(footer)}</div>`:''}`
}
function badge(t){let typ=String(t||'').toUpperCase(),cl=typ.includes('CRITICAL')?'critical':typ.includes('HIGH')||typ.includes('FAILED')?'high':typ.includes('WATCH')?'watch':typ.includes('SENT')||typ.includes('APPROVED')||typ.includes('COMPLETED')||typ.includes('NORMAL')?'good':'neutral';return `<span class="badge ${cl}">${esc(String(t||'—').replaceAll('_',' '))}</span>`}
function box(title,inside,cls=''){return `<section class="panel ${cls}">${title?`<div class="panel-head"><h2>${esc(title)}</h2></div>`:''}${inside}</section>`}
function kpi(label,value,desc,trend,ic=colors.blue){return `<div class="metric"><div class="metric-label">${esc(label)}</div><div class="metric-val mono">${esc(value)}</div>${spark(trend,ic)}<div class="metric-delta ${ic===colors.red?'danger':ic===colors.green?'positive':'muted'}">${esc(desc)}</div></div>`}
function labelDelta(current,baseline,inverse=false){if(baseline==null||Math.abs(baseline)<1e-9)return 'Historical reference unavailable';let v=(current-baseline)/baseline*100,arrow=v>=0?'↑':'↓';return `${arrow} ${n(Math.abs(v),1)}% vs comparable baseline`}
function labelCase(x){return String(x||'').replaceAll('_',' ').toLowerCase().replace(/\b\w/g,m=>m.toUpperCase())}
function selected(){return state.data.selected_incident}
function metricCards(d){let s=d.current,b=d.baseline||{},trend=d.timeline.filter(p=>p.timestamp<=at());let slaColor=s.sla>=.90?colors.green:s.sla>=.80?colors.amber:colors.red;let abColor=s.abandon_rate<=.05?colors.green:s.abandon_rate<=.08?colors.amber:colors.red;return `<div class="kpi-grid">${kpi('Service Level',percent(s.sla),b.sla?labelDelta(s.sla,b.sla):'Observed this interval',trend.map(p=>p.sla),slaColor)}${kpi('Volume / 30 min',n(s.offered_calls),b.offered_calls?labelDelta(s.offered_calls,b.offered_calls):'Calls offered',trend.map(p=>p.volume),colors.blue)}${kpi('Average Handle Time',n(s.aht,0)+'s',b.aht?labelDelta(s.aht,b.aht):'Seconds / answered call',trend.map(p=>p.aht),colors.violet)}${kpi('Available Agents',n(s.available_agents),`${n(s.required_agents)} required`,trend.map(p=>p.available_agents),colors.amber)}${kpi('Abandon Rate',percent(s.abandon_rate),`${n(s.abandoned_calls)} abandoned calls`,trend.map(p=>p.abandon),abColor)}</div>`}
function forecastPlot(d,title='Service level — observed & projected'){let data=d.timeline,now=at(),times=data.map(z=>z.time),sla=data.map(z=>z.timestamp<=now?z.sla:null),future=data.map(_=>null);let nowIdx=data.findIndex(z=>z.timestamp===now),fc=d.forecast.slice().sort((a,b)=>a.horizon_minutes-b.horizon_minutes);
  if(nowIdx>=0){future[nowIdx]=data[nowIdx].sla;fc.forEach(f=>{let idx=nowIdx+Number(f.horizon_minutes)/30;if(Number.isInteger(idx)&&idx<future.length)future[idx]=Number(f.predicted_sla_naive_trend)*100})}
  return plot({title,points:times,lines:[{label:'Observed (%)',values:sla,color:colors.blue,fill:true},{label:'Trend estimate (uncalibrated)',values:future,color:colors.red,dashed:true}],target:90,targetLabel:'Service target 90%',min:0,max:100,footer:'SYNTHETIC REPLAY · Forecast is a naive backtest estimate, not a validated probability or no-action causal forecast.'})}
function fullDayForecastPanel(d,title='Full-Day Performance Forecast'){let fc=d.full_day_forecast||{},act=fc.actual_to_date||{},proj=fc.projected_full_day||{},rem=fc.predicted_remaining||{},intervals=fc.all_intervals||[];
  if(!intervals.length)return box(title,forecastPlot(d,title));
  let times=intervals.map(z=>z.time),lastObsIdx=-1;
  intervals.forEach((z,i)=>{if(z.kind==='OBSERVED')lastObsIdx=i});
  let obsSla=intervals.map((z,i)=>i<=lastObsIdx?z.sla_pct:null),projSla=intervals.map((z,i)=>i>=lastObsIdx?z.sla_pct:null);
  let slaGap=proj.sla_pct!=null?(proj.sla_pct-90.0):0,gapSign=slaGap>=0?'+':'',gapCls=slaGap>=0?'positive':(proj.sla_pct<80?'danger':'amber');
  let chips=`<div class="eod-kpi-row">
    <div class="eod-chip featured"><small>EOD Projected SLA</small><strong class="${gapCls}">${proj.sla_pct!=null?n(proj.sla_pct,1)+'%':'—'}</strong><span class="${gapCls}">Target 90.0% · ${gapSign}${n(slaGap,1)} pp</span></div>
    <div class="eod-chip"><small>Observed to Date</small><strong class="blue">${act.sla_pct!=null?n(act.sla_pct,1)+'%':'—'}</strong><span>${act.intervals_count||0}/48 intervals · ${n(act.offered_calls)} calls</span></div>
    <div class="eod-chip"><small>Predicted Remaining</small><strong class="cyan">${rem.sla_pct!=null?n(rem.sla_pct,1)+'%':'—'}</strong><span>${rem.intervals_count||0} intervals · ${n(rem.offered_calls)} calls</span></div>
    <div class="eod-chip"><small>Total Day Demand</small><strong>${n(proj.offered_calls)} calls</strong><span>${n(proj.answered_calls)} answered</span></div>
    <div class="eod-chip"><small>Projected EOD Backlog</small><strong class="${(proj.end_backlog||0)>0?'danger':'good'}">${n(proj.end_backlog||0)}</strong><span>Zero backlog conserved</span></div>
  </div>`;
  let plotSvg=plot({title:'',points:times,lines:[{label:'Observed SLA (%)',values:obsSla,color:colors.blue,fill:true},{label:'Projected EOD SLA (%)',values:projSla,color:colors.cyan,dashed:true}],target:90,targetLabel:'SLA Target 90%',min:0,max:100,footer:'Hybrid Walk-Forward EOD Projection · Empirical backtest error 0.46 pp on Queue A · Prior 4-wk seasonal baseline'});
  return `<section class="panel eod-panel"><div class="panel-head"><div><h2>${esc(title)}</h2><span class="panel-sub">Reconciled end-of-day projection: observed actuals combined with seasonal-residual baselines</span></div><div class="tag-row"><span class="badge ${proj.target_breached?'critical':'good'}">${proj.target_breached?'⚠ EOD SLA Breach':'✓ EOD Target Met'}</span><span class="badge neutral">${act.intervals_count||35}/48 Elapsed</span></div></div>${chips}${plotSvg}</section>`}
function watchoutsView(d){let wList=d.watchouts||[];if(!wList.length)return '<div class="empty">No operational watch-outs detected across Intraday, Daily, Weekly, or Monthly horizons.</div>';
  return `<div class="watchout-list">${wList.map(w=>`<div class="watchout-card ${esc(w.severity)}"><div class="watchout-top"><span class="watchout-title"><span class="badge ${w.severity==='CRITICAL'?'critical':w.severity==='HIGH'?'high':w.severity==='WATCH'?'watch':'good'}">${esc(w.severity)}</span><span class="badge neutral">${esc(String(w.horizon||'').toUpperCase())}</span><b>${esc(w.queue)} — ${esc(w.metric)}</b></span><span class="tiny muted mono">${esc(w.watchout_id)}</span></div><div class="watchout-body"><div><span class="muted">Observed:</span> <strong>${esc(w.observed)}</strong> <span class="tiny muted">(${esc(w.expected_historical)})</span></div><div><span class="muted">Trajectory:</span> <b class="${w.severity==='CRITICAL'||w.severity==='HIGH'?'danger':'blue'}">${esc(w.trajectory)}</b></div><div style="grid-column:1/-1"><span class="muted">Projected Next:</span> <span>${esc(w.projected_next)}</span></div></div><div class="watchout-rec">✦ <b>Action Review:</b> ${esc(w.recommended_review)}</div><div class="watchout-footer"><span>Owner: <b>${esc(w.owner)}</b></span><span>${(w.evidence_ids||[]).map(id=>`<span class="chat-evidence-tag">${esc(id)}</span>`).join('')}</span></div></div>`).join('')}</div>`}
function formatChatReply(text){let s=esc(text||'');s=s.replace(/\*\*(.*?)\*\*/g,'<b>$1</b>');s=s.replace(/`([^`]+)`/g,'<code class="chat-evidence-tag">$1</code>');s=s.replace(/(?:^|\n)[*-]\s+(.+)/g,'<br/>• $1');s=s.replace(/\n\n+/g,'<br/><br/>').replace(/\n/g,'<br/>');return s}
function chatWidget(d){let btn=`<button class="chat-float-btn" id="btn-toggle-chat" aria-label="Open Opsentia Chat">${icon('spark',16)}<span>Opsentia Chat</span><span class="badge ${d.meta.gemini_verified?'good':'neutral'}" style="font-size:9.5px;padding:2px 6px">${d.meta.gemini_verified?'Gemini 3.5':'Deterministic'}</span></button>`;
  if(!state.chatOpen)return btn;
  let msgs=state.chatMessages||[];
  let msgList=msgs.map(m=>{let cls=m.sender==='user'?'user':(m.isSecurity?'security':'assistant');let tcs=(m.tool_calls||[]).map(t=>`<span class="chat-evidence-tag">⚙ ${esc(t.name)}</span>`).join('');let evs=(m.evidence||[]).map(e=>`<span class="chat-evidence-tag">🔗 ${esc(e.source_id)}</span>`).join('');return `<div class="chat-msg ${cls}">${formatChatReply(m.text)}${(tcs||evs)?`<div style="margin-top:4px">${tcs}${evs}</div>`:''}</div>`}).join('');
  if(state.chatLoading)msgList+=`<div class="chat-msg assistant"><span class="tiny muted">✦ Querying bounded analytical tools…</span></div>`;
  return btn+`<div class="chat-drawer" role="dialog" aria-label="Opsentia Assistant Chat"><div class="chat-header"><h3>${icon('spark',15)} Opsentia Operational Assistant</h3><button class="secondary" id="btn-chat-close" style="padding:2px 7px;font-size:11px" title="Minimize chat">✕</button></div><div class="chat-context-bar"><span>Context: <b>${esc(state.queue)}</b> · Replay: <b>${esc(hh(at()))}</b></span><span class="badge ${d.meta.gemini_verified?'good':'neutral'}" style="font-size:9px">${d.meta.gemini_verified?'AI Live':'Fallback'}</span></div><div class="chat-prompts"><button class="chat-pill" data-prompt="Why is SLA falling today on ${esc(state.queue)}?">Why is SLA falling today?</button><button class="chat-pill" data-prompt="Project EOD SLA and backlog for ${esc(state.queue)}">Full-Day EOD Forecast</button><button class="chat-pill" data-prompt="Compare ${esc(state.queue)} performance vs other queues">Compare Queues</button><button class="chat-pill" data-prompt="What are the active COIL watch-outs?">Check Watch-Outs</button><button class="chat-pill" data-prompt="What is the donor queue SLA protection rule?">Donor Queue Rules</button></div><div class="chat-messages" id="chat-messages-container">${msgList}</div><form class="chat-input-bar" id="chat-form"><input class="chat-input" id="chat-input-field" placeholder="Ask about SLA, forecasts, policies..." value="${esc(state.chatInput||'')}" autocomplete="off" /><button class="chat-send-btn" type="submit">Send →</button></form></div>`}
async function sendChatMessage(customPrompt){let msg=(customPrompt||state.chatInput||'').trim();if(!msg||state.chatLoading)return;
  state.chatMessages.push({sender:'user',text:msg});state.chatInput='';state.chatLoading=true;render();scrollChatToBottom();
  try{let r=await fetch('/api/assistant/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:msg,queue:state.queue,as_of:at(),grain:state.metricsHorizon||'intraday'})});
    if(r.ok){let res=await r.json();let isSec=res.ai_mode==='SECURITY_GUARDRAIL_BLOCKED';state.chatMessages.push({sender:'assistant',text:res.answer||res.reply||'No answer available.',isSecurity:isSec,tool_calls:res.tool_calls||[],evidence:res.evidence||[]})}
    else{state.chatMessages.push({sender:'assistant',text:'System notice: Unable to contact assistant gateway ('+r.status+').'})}
  }catch(err){state.chatMessages.push({sender:'assistant',text:'Connection notice: Assistant request failed ('+err.message+').'})}
  finally{state.chatLoading=false;render();scrollChatToBottom()}}
function scrollChatToBottom(){setTimeout(()=>{let b=$('#chat-messages-container');if(b)b.scrollTop=b.scrollHeight},35)}
function drivers(d){let e=d.evidence.slice(0,4);if(e.length===0)return '<div class="empty">No linked investigation evidence for this timestamp.</div>';return `<div class="drivers">${e.map((z,i)=>`<div class="driver"><span class="driver-num">${i+1}</span><div style="min-width:0;flex:1"><div class="driver-title">${esc(labelCase(z.metric))}</div><div class="driver-detail">Observed ${n(z.observed_value,1)} · prior comparable ${z.comparable_baseline_4wk!=null?n(z.comparable_baseline_4wk,1):'n/a'}</div></div>${z.relative_deviation_pct!=null?`<b class="${Math.abs(z.relative_deviation_pct)>10?'danger':'muted'} small">${n(z.relative_deviation_pct,1)}%</b>`:''}</div>`).join('')}</div>`}
function incidentRows(d){return `<div class="incident-list">${d.active_incidents.length?d.active_incidents.map(i=>`<div class="incident-item">${badge(i.severity)}<div><b>${esc(i.queue)} — ${esc(labelCase(i.type))}</b><span class="tiny muted">${i.sla}% SLA · Started ${hh(i.start)}</span></div><div class="right"><strong class="${isRed(i.severity)?'danger':'blue'}">${i.sla}%</strong></div><button class="secondary" data-page="investigation" data-queue="${esc(i.queue)}">Investigate →</button></div>`).join(''):'<div class="empty">No active incidents at this replay time.</div>'}</div>`}
function scenariosView(d){const choices=d.scenarios;return choices.length?choices.map((s,i)=>`<div class="recommend-card ${i===1?'featured':''}"><div class="panel-head"><span class="rec-title">Option ${i+1} — ${esc(labelCase(s.scenario_type))}</span>${i===0?badge('No-action baseline'):badge('Simulation input')}</div><div class="panel-sub">${Number(s.agents_to_add||0)>0?'Add '+n(s.agents_to_add)+' temporary agents':Number(s.agents_to_transfer||0)>0?'Transfer '+n(s.agents_to_transfer)+' agents from '+esc(s.donor_queue):'Keep current staffing'} · ${n(s.duration_hours,1)} hours</div><div class="rec-card-grid"><div><strong class="blue">${n(d.current.available_agents)}</strong><span>Agents before</span></div><div><strong class="amber">${n(d.current.required_agents)}</strong><span>Agents required</span></div><div><strong>$${n(s.estimated_incremental_cost_usd)}</strong><span>Cost estimate</span></div></div><div class="tag-row">${badge('Current constraint review needed')}<span class="badge neutral">SLA uplift not modeled</span></div><button class="secondary" style="margin-top:10px" data-dialog="scenario-${esc(s.scenario_id)}">View assumptions →</button></div>`).join(''):'<div class="empty">No active incident scenarios requiring mitigation.</div>'}
function compactScenarios(d){if(!d.scenarios||d.scenarios.length===0){return `<div class="rec-compact"><div class="panel-head"><span class="rec-title">${esc(d.meta.queue)} · Normal Operations</span><span class="badge good">Healthy SLA</span></div><div class="tag-row"><span class="positive">Observed SLA ${percent(d.current.sla)} meets operational targets.</span></div><div class="rec-compact-foot"><span class="tiny muted">No intervention or overtime required</span></div></div>`}return d.scenarios.slice(0,3).map((s,i)=>`<div class="rec-compact ${i===1?'highlight':''}"><div class="panel-head"><span class="rec-title">Option ${i+1} · ${esc(labelCase(s.scenario_type))}</span>${i===0?badge('Baseline'):badge('Unvalidated')}</div><div class="tag-row"><span>${Number(s.agents_to_add||0)+Number(s.agents_to_transfer||0)} agents</span><span class="muted">·</span><span class="muted">$${n(s.estimated_incremental_cost_usd)} estimated</span><span class="muted">·</span><span class="muted">${n(s.duration_hours,1)} hours</span></div><div class="rec-compact-foot"><span class="tiny muted">Projected SLA requires validated model</span><button data-dialog="scenario-${esc(s.scenario_id)}" class="secondary">Inspect →</button></div></div>`).join('')}
function notificationCounters(d){const z=d.notification_summary;return `<div class="notification-metrics"><div><strong>${n(z.TOTAL_EVENTS||0)}</strong><small>Recorded events</small></div><div style="background:#07372e"><strong class="positive">${n(z.SIMULATED_SENT||0)}</strong><small>Simulated sent</small></div><div style="background:#3a1b2c"><strong class="danger">${n(z.SIMULATED_FAILED||0)}</strong><small>Simulated failed</small></div><div><strong>${n(z.SIMULATED_SUPPRESSED||0)}</strong><small>Suppressed</small></div></div><div class="panel-footer">Not evidence of delivery to a real recipient.</div>`}
function notificationsList(d,num=7){return `<div class="table-wrap"><table class="mini-table"><thead><tr><th>Time</th><th>Recipient / Channel</th><th>Reason</th><th>Result</th></tr></thead><tbody>${d.notifications.slice(0,num).map(v=>`<tr><td class="mono">${hh(v.timestamp)}</td><td>${esc(v.recipient_role)}<br/><span class="tiny muted">${esc(v.channel)}</span></td><td>${esc(labelCase(v.event_reason))}</td><td>${badge(v.delivery_status)}</td></tr>`).join('')}</tbody></table></div>`}
function banner(d,title){let i=selected(),curSla=d.current.sla;let sev=i?.severity||(curSla<.80?'CRITICAL':curSla<.85?'HIGH':curSla<.90?'WATCH':'NORMAL');let isGood=sev==='NORMAL',isWatch=sev==='WATCH';let bannerCls=isGood?'good':isWatch?'watch':'';let pillCls=isGood?'good':isWatch?'watch':'';let pillText=isGood?'✓ NORMAL':isWatch?'◉ WATCH':sev==='CRITICAL'?'⚠ CRITICAL':'⚠ HIGH';let queueCls=isGood?'positive':isWatch?'blue':'danger';let f=d.forecast[0];let forecast=f&&f.predicted_sla_naive_trend!=null?percent(f.predicted_sla_naive_trend):'—';let slaGap=n((curSla-.90)*100,1);return `<div class="top-banner ${bannerCls}"><span class="critical-pill ${pillCls}">${pillText}</span><div><h2><span class="${queueCls}">${esc(d.meta.queue)}</span> — ${esc(title||(isGood?'Operating within SLA targets':'Emerging operational risk'))}</h2><p>Current SLA ${percent(curSla)} against 90% service target. ${f?'30-minute naive trend estimate: '+forecast+'.':''} ${isGood?'All operational metrics stable.':'Investigate evidence before taking action.'}</p></div><div class="banner-stat ${bannerCls}"><strong>30m – 2h</strong><span>COIL Horizons</span></div><div class="banner-impact ${bannerCls}"><small class="muted">SLA Gap</small><strong class="${curSla>=.90?'positive':'danger'}">${curSla>=.90?'+':''}${slaGap}pp</strong><span class="tiny muted">vs target</span></div></div>`}
function live(d){return `<div class="two-col"><div class="stack">${banner(d)}${metricCards(d)}${fullDayForecastPanel(d)}<div class="grid2">${box('Active Incidents ('+d.active_incidents.length+')',incidentRows(d))}${box('Evidence-backed drivers',drivers(d))}</div><div class="grid2">${box('Historical Pattern Matches', d.matches.length?d.matches.map(m=>`<div class="list-row"><div><h3>${esc(m.matched_incident_id)}</h3><p>${esc(m.matched_date)} · ${m.same_queue?'Same queue':'Cross-queue comparison'}</p></div><span class="badge neutral">Rank ${m.rank}</span></div>`).join('')+'<div class="panel-footer">Heuristic matching · not a calibrated probability.</div>':'<div class="empty">No historical matches found.</div>')}${box('Opsentia AI Watch-Outs (' + (d.watchouts?.length || 0) + ')', watchoutsView(d))}</div>${box('',`<div class="info-banner"><strong>✦ Opsentia intelligence</strong><span>COIL continuous early warning and Gemini assistant tools active.</span><button class="primary" data-page="investigation">Examine evidence →</button></div>`)}</div><div class="stack">${box('Recommended decision scenarios',`<p class="panel-sub">Operational scenarios from fixture inputs; no asserted uplift.</p>${compactScenarios(d)}<button class="link" data-page="decision" style="margin-top:5px">Compare every option in Decision Lab →</button>`)}${box('Notifications & audit',notificationCounters(d)+'<div class="panel-divider"></div>'+notificationsList(d,7))}</div></div>`}
function allMetrics(d){
  let h=state.metricsHorizon||'intraday';
  let isPart=h==='intraday'?(hh(at())<'23:30'):(h==='day'?(d.daily||[]).some(x=>x.is_partial):(h==='week'?(d.weekly||[]).some(x=>x.is_partial):(d.monthly||[]).some(x=>x.is_partial)));
  let horizonBar=`<div class="horizon-bar"><div class="horizon-pills"><span class="muted" style="font-size:12px;margin-right:4px">Horizon:</span><button class="horizon-pill ${h==='intraday'?'active':''}" data-horizon="intraday">Intraday (30m)</button><button class="horizon-pill ${h==='day'?'active':''}" data-horizon="day">Daily (32d)</button><button class="horizon-pill ${h==='week'?'active':''}" data-horizon="week">Weekly (18w)</button><button class="horizon-pill ${h==='month'?'active':''}" data-horizon="month">Monthly (7m)</button></div>${isPart?`<span class="partial-warning-tag">⚠ In-Progress ${h.toUpperCase()} · Recomputed strictly &lt;= ${hh(at())}</span>`:`<span class="badge good">Completed Period Coverage</span>`}</div>`;

  let content='';
  if(h==='intraday'){
    let r=d.current,sm=d.summary,series=d.timeline.filter(x=>x.timestamp<=at());
    const smallPlot=(title,key,color,tgt=null,min=null,max=null)=>plot({title,points:d.timeline.map(x=>x.time),lines:[{label:'Observed',values:d.timeline.map(x=>x.timestamp<=at()?x[key]:null),color,fill:true}],target:tgt,targetLabel:'Reference',height:199,min,max,xLabels:5,footer:'Selected queue · '+day(at())});
    let cards=[['Offered calls',n(sm.offered_calls),'All queues at selected time','volume',colors.blue],['SLA',percent(r.sla),'Selected queue','sla',colors.red],['AHT',n(r.aht)+'s','Selected queue','aht',colors.violet],['Abandon rate',percent(r.abandon_rate),'Measured calls','abandon',colors.red],['Answered',n(sm.answered_calls),'All queues','volume',colors.blue],['Occupancy',percent(r.occupancy),'Selected queue','occupancy',colors.cyan],['Available agents',n(r.available_agents),'Selected queue','available_agents',colors.amber],['Backlog',n(r.backlog),'Selected queue','backlog',colors.red],['Forecast accuracy',percent(sm.forecast_accuracy),'All queues · WAPE-based','accuracy',colors.violet]];
    content=`<div class="metric-grid-9">${cards.map(([title,value,desc,key,c])=>kpi(title,value,desc,series.slice(-12).map(x=>x[key]),c)).join('')}</div><div class="four-grid" style="margin-top:12px">${box('',smallPlot('Service Level (%)','sla',colors.blue,90,0,100))}${box('',smallPlot('AHT (seconds)','aht',colors.violet))}${box('',smallPlot('Offered Volume','volume',colors.blue))}${box('',smallPlot('Abandonment (%)','abandon',colors.red,5,0,null))}${box('',smallPlot('Staffing available','available_agents',colors.amber))}${box('',smallPlot('Occupancy (%)','occupancy',colors.cyan,85,0,100))}${box('',smallPlot('Backlog','backlog',colors.amber))}${box('',smallPlot('Forecast Accuracy (%)','accuracy',colors.violet,90,0,100))}</div>`;
  } else if(h==='day'){
    let days=d.daily||[],curD=days.at(-1)||{};
    let totOffered=days.reduce((a,b)=>a+(b.offered_calls||0),0);
    let cards=[['32-Day Total Demand',n(totOffered),'Observed offered calls','volume',colors.blue],['Daily SLA (Today)',percent(curD.sla),curD.is_partial?'In-progress day <= '+hh(at()):'Full day completed','sla',curD.sla>=0.9?colors.green:colors.red],['Daily AHT',n(curD.aht||curD.aht_seconds)+'s','Seconds / call','aht',colors.violet],['Daily Abandon Rate',percent(curD.abandon_rate),n(curD.abandoned_calls)+' calls','abandon',colors.red],['Peak Queue Backlog',n(curD.peak_backlog||curD.end_backlog||0),'Peak calls in queue','backlog',colors.amber],['Average Duty Staff',n(curD.avg_agents||curD.avg_available_agents||0,1),'Average available agents','available_agents',colors.cyan]];
    content=`<div class="metric-grid-9">${cards.map(([title,value,desc,key,c])=>kpi(title,value,desc,days.slice(-12).map(x=>x[key]),c)).join('')}</div><div class="four-grid" style="margin-top:12px">${box('',plot({title:'Daily Service Level (%)',points:days.map(x=>String(x.date).slice(5)),lines:[{label:'SLA (%)',values:days.map(x=>x.sla*100),color:colors.blue,fill:true}],target:90,targetLabel:'Target 90%',height:199,min:0,max:100,xLabels:6,footer:'32-Day historical daily SLA'}))}${box('',plot({title:'Daily Offered Calls',points:days.map(x=>String(x.date).slice(5)),lines:[{label:'Offered calls',values:days.map(x=>x.offered_calls),color:colors.cyan,fill:true}],height:199,xLabels:6,footer:'32-Day daily volume'}))}${box('',plot({title:'Daily AHT (seconds)',points:days.map(x=>String(x.date).slice(5)),lines:[{label:'AHT (s)',values:days.map(x=>x.aht||x.aht_seconds),color:colors.violet,fill:true}],height:199,xLabels:6,footer:'32-Day daily handle time'}))}${box('',plot({title:'Daily Abandon Rate (%)',points:days.map(x=>String(x.date).slice(5)),lines:[{label:'Abandon (%)',values:days.map(x=>x.abandon_rate*100),color:colors.red,fill:true}],target:5,targetLabel:'Max 5%',height:199,min:0,max:20,xLabels:6,footer:'32-Day daily abandon rate'}))}</div>`;
  } else if(h==='week'){
    let weeks=d.weekly||[],curW=weeks.at(-1)||{};
    let totOffered=weeks.reduce((a,b)=>a+(b.offered_calls||0),0);
    let cards=[['18-Week Total Demand',n(totOffered),'Observed offered calls','volume',colors.blue],['Weekly SLA (Current)',percent(curW.sla),curW.is_partial?'In-progress week <= '+hh(at()):'Full week completed','sla',curW.sla>=0.9?colors.green:colors.red],['Weekly AHT',n(curW.aht||curW.aht_seconds)+'s','Seconds / call','aht',colors.violet],['Weekly Abandon Rate',percent(curW.abandon_rate),n(curW.abandoned_calls)+' calls','abandon',colors.red],['Peak Queue Backlog',n(curW.peak_backlog||curW.end_backlog||0),'Peak calls in queue','backlog',colors.amber],['Average Duty Staff',n(curW.avg_agents||curW.avg_available_agents||0,1),'Average available agents','available_agents',colors.cyan]];
    content=`<div class="metric-grid-9">${cards.map(([title,value,desc,key,c])=>kpi(title,value,desc,weeks.slice(-12).map(x=>x[key]),c)).join('')}</div><div class="four-grid" style="margin-top:12px">${box('',plot({title:'Weekly Service Level (%)',points:weeks.map(x=>String(x.period).slice(-5)),lines:[{label:'SLA (%)',values:weeks.map(x=>x.sla*100),color:colors.blue,fill:true}],target:90,targetLabel:'Target 90%',height:199,min:0,max:100,xLabels:6,footer:'18-Week historical weekly SLA'}))}${box('',plot({title:'Weekly Offered Calls',points:weeks.map(x=>String(x.period).slice(-5)),lines:[{label:'Offered calls',values:weeks.map(x=>x.offered_calls),color:colors.cyan,fill:true}],height:199,xLabels:6,footer:'18-Week weekly volume'}))}${box('',plot({title:'Weekly AHT (seconds)',points:weeks.map(x=>String(x.period).slice(-5)),lines:[{label:'AHT (s)',values:weeks.map(x=>x.aht||x.aht_seconds),color:colors.violet,fill:true}],height:199,xLabels:6,footer:'18-Week weekly handle time'}))}${box('',plot({title:'Weekly Abandon Rate (%)',points:weeks.map(x=>String(x.period).slice(-5)),lines:[{label:'Abandon (%)',values:weeks.map(x=>x.abandon_rate*100),color:colors.red,fill:true}],target:5,targetLabel:'Max 5%',height:199,min:0,max:20,xLabels:6,footer:'18-Week weekly abandon rate'}))}</div>`;
  } else {
    let months=d.monthly||[],curM=months.at(-1)||{};
    let totOffered=months.reduce((a,b)=>a+(b.offered_calls||0),0);
    let cards=[['7-Month Total Demand',n(totOffered),'Observed offered calls','volume',colors.blue],['Monthly SLA (Current)',percent(curM.sla),curM.is_partial?'In-progress month <= '+hh(at()):'Full month completed','sla',curM.sla>=0.9?colors.green:colors.red],['Monthly AHT',n(curM.aht||curM.aht_seconds)+'s','Seconds / call','aht',colors.violet],['Monthly Abandon Rate',percent(curM.abandon_rate),n(curM.abandoned_calls)+' calls','abandon',colors.red],['Peak Queue Backlog',n(curM.peak_backlog||curM.end_backlog||0),'Peak calls in queue','backlog',colors.amber],['Average Duty Staff',n(curM.avg_agents||curM.avg_available_agents||0,1),'Average available agents','available_agents',colors.cyan]];
    content=`<div class="metric-grid-9">${cards.map(([title,value,desc,key,c])=>kpi(title,value,desc,months.map(x=>x[key]),c)).join('')}</div><div class="four-grid" style="margin-top:12px">${box('',plot({title:'Monthly Service Level (%)',points:months.map(x=>x.period),lines:[{label:'SLA (%)',values:months.map(x=>x.sla*100),color:colors.blue,fill:true}],target:90,targetLabel:'Target 90%',height:199,min:0,max:100,xLabels:7,footer:'7-Month historical monthly SLA'}))}${box('',plot({title:'Monthly Offered Calls',points:months.map(x=>x.period),lines:[{label:'Offered calls',values:months.map(x=>x.offered_calls),color:colors.cyan,fill:true}],height:199,xLabels:7,footer:'7-Month monthly volume'}))}${box('',plot({title:'Monthly AHT (seconds)',points:months.map(x=>x.period),lines:[{label:'AHT (s)',values:months.map(x=>x.aht||x.aht_seconds),color:colors.violet,fill:true}],height:199,xLabels:7,footer:'7-Month monthly handle time'}))}${box('',plot({title:'Monthly Abandon Rate (%)',points:months.map(x=>x.period),lines:[{label:'Abandon (%)',values:months.map(x=>x.abandon_rate*100),color:colors.red,fill:true}],target:5,targetLabel:'Max 5%',height:199,min:0,max:20,xLabels:7,footer:'7-Month monthly abandon rate'}))}</div>`;
  }

  return `<div class="page-title"><div><h1>All Metrics</h1><p>Multi-horizon workforce and operational decision intelligence · Replay: ${esc(at())}</p></div>${badge('MULTI-HORIZON')}</div>${horizonBar}${content}<div style="margin-top:14px">${fullDayForecastPanel(d)}</div><div class="two-col" style="margin-top:14px"><div class="stack">${box('Opsentia AI Watch-Outs (' + (d.watchouts?.length || 0) + ')', watchoutsView(d))}</div><div class="stack">${box('Queue Comparison',`<div class="table-wrap"><table class="mini-table"><thead><tr><th>Queue</th><th>SLA</th><th>Volume</th><th>AHT</th><th>Abandon</th><th>Gap</th></tr></thead><tbody>${d.queue_comparison.map(x=>`<tr><td>${esc(x.queue)}</td><td class="${x.sla<.75?'danger':'positive'}">${percent(x.sla)}</td><td>${n(x.offered_calls)}</td><td>${n(x.aht)}s</td><td>${percent(x.abandon_rate)}</td><td>${n(x.required_agents-x.available_agents,1)}</td></tr>`).join('')}</tbody></table></div>`) }${box('Performance context',`<div class="kv"><span>As of</span><strong>${esc(at())}</strong></div><div class="kv"><span>Queue</span><strong>${esc(d.meta.queue)}</strong></div><div class="kv"><span>Active Horizon</span><strong>${esc(h.toUpperCase())}</strong></div><div class="kv"><span>EOD SLA Projection</span><strong>${percent(d.full_day_forecast?.projected_full_day?.sla)}</strong></div><div class="kv"><span>Data origin</span><strong>Zero-leakage synthetic fixtures</strong></div>`) }</div></div>`;
}
function investigation(d){let i=selected(),e=d.evidence,inv=state.investigation;
let invCard=inv?`<div class="recommend-card featured" style="margin-bottom:12px"><div class="panel-head"><b>Model: ${esc(inv.model_id)}</b>${badge(inv.investigation_status)}</div><div class="kv"><span>Mode</span><strong>${esc(inv.ai_mode)}</strong></div><div class="kv"><span>Trace ID</span><strong class="mono small">${esc(inv.trace_id)}</strong></div><p class="panel-sub" style="margin:8px 0">${esc(inv.executive_summary)}</p><div class="list-head" style="margin-top:8px"><b>Tool calls executed (${inv.tool_calls.length}):</b></div>${inv.tool_calls.map(tc=>`<div class="list-row"><span>${esc(tc.name)}</span><span class="badge neutral">${tc.duration_ms}ms</span></div>`).join('')}<div class="panel-footer" style="margin-top:8px">Recommendation: ${esc(inv.recommendation.action)}</div></div>`:`<div class="empty" style="text-align:left">${icon('spark')} <b>Investigation Engine Ready</b><p>Analyze operational signals, 10 read-only analytical tools, and historical baselines.</p><button class="primary" id="btn-run-investigation" style="margin-top:10px">✦ Run Investigation (Gemini / COIL)</button></div>`;
return `<div class="two-col"><div class="stack">${banner(d,'Investigation: '+labelCase(i?.type||'Operational risk'))}${metricCards(d)}${box('',plot({title:'Incident timeline — observed indicators',points:d.timeline.map(x=>x.time),lines:[{label:'SLA (%)',values:d.timeline.map(x=>x.timestamp<=at()?x.sla:null),color:colors.blue,fill:true},{label:'Occupancy (%)',values:d.timeline.map(x=>x.timestamp<=at()?x.occupancy:null),color:colors.violet}],target:90,min:0,max:110,footer:'Observed values through replay time; these lines do not establish causality.'}))}<div class="dual-grid">${box('Evidence register',e.length?`<div class="table-wrap"><table class="mini-table"><thead><tr><th>Metric</th><th>Observed</th><th>Comparable</th><th>Deviation</th></tr></thead><tbody>${e.slice(0,9).map(v=>`<tr><td>${esc(labelCase(v.metric))}</td><td>${n(v.observed_value,1)}</td><td>${n(v.comparable_baseline_4wk,1)}</td><td>${v.relative_deviation_pct!=null?n(v.relative_deviation_pct,1)+'%':'—'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No evidence for this incident.</div>')}${box('Hypotheses tested',inv?inv.hypotheses.map(h=>`<div class="list-row"><div style="flex:1"><span>${esc(h.label)}</span><p class="tiny muted">${esc(h.limitations||'')}</p></div>${badge(h.status)}</div>`).join(''):['Demand exceeded forecast','Average handling time increased','Scheduled capacity became unavailable','Workflow or case complexity changed'].map((t,j)=>`<div class="list-row"><span>${j+1}. ${t}</span><span class="badge neutral">Pending run</span></div>`).join(''))}</div>${box('Historical analogues',d.matches.slice(0,5).map(v=>`<div class="list-row"><div><h3>${esc(v.matched_incident_id)}</h3><p>${esc(v.matched_date)} · ${esc(v.match_method)}</p></div><span class="badge neutral">Rank ${v.rank}</span></div>`).join('')||'<div class="empty">No historical matches.</div>')}</div><div class="stack">${box('Gemini / COIL Investigation Trace',invCard)}${box('Evidence & Signals',`<p class="panel-sub">Grounded in synthetic operational and knowledge fixtures</p>${drivers(d)}`)}${box('Enterprise knowledge',d.knowledge.slice(0,7).map(k=>`<div class="list-row"><div><h3>${esc(k.title)}</h3><p>${esc(k.category)} · ${esc(k.approval_status)}</p></div><button data-dialog="doc-${esc(k.document_id)}" class="link">Read →</button></div>`).join(''))}</div></div>`}
function decision(d){const scenario=d.scenarios,cur=d.current;return `<div class="two-col"><div class="stack">${banner(d,'Decision Lab — compare available actions')}${metricCards(d)}${box('',forecastPlot(d,'Baseline forecast (no causal intervention model)'))}${box('Scenario Comparison — staffing inputs',`<div class="table-wrap"><table class="mini-table"><thead><tr><th>Scenario</th><th>Add / Transfer</th><th>Staff gap after</th><th>Duration</th><th>Cost estimate</th><th>Projected SLA</th><th>Decision</th></tr></thead><tbody>${scenario.map(s=>{let a=Number(s.agents_to_add||0)+Number(s.agents_to_transfer||0),gap=Math.max(0,Number(cur.required_agents||0)-Number(cur.available_agents||0)-a);return `<tr><td>${esc(labelCase(s.scenario_type))}</td><td>${a} agents</td><td class="${gap>0?'danger':'positive'}">${gap}</td><td>${n(s.duration_hours,1)}h</td><td>$${n(s.estimated_incremental_cost_usd)}</td><td class="${s.projected_sla?'positive':'muted'}">${s.projected_sla?percent(s.projected_sla):'Click inspect'}</td><td><button data-dialog="scenario-${esc(s.scenario_id)}" class="secondary">Inspect</button></td></tr>`}).join('')}</tbody></table></div><p class="footnote">The candidate scenarios contain costs and staffing inputs. Click inspect to simulate via the verified Erlang capacity model with donor queue protection.</p>`)}${box('Cross-queue guardrails',`<div class="dual-grid"><div class="kv"><span>Current queue SLA</span><strong>${percent(cur.sla)}</strong></div><div class="kv"><span>Current staffing gap</span><strong>${n(Math.max(0,cur.required_agents-cur.available_agents))}</strong></div><div class="kv"><span>Donor protection</span><strong>Enforced via /api/simulations</strong></div><div class="kv"><span>Approval</span><strong>Required for execution</strong></div></div>`)}</div><div class="stack">${box('Scenario inputs',scenariosView(d))}${box('Decision Contract',`<div class="kv"><span>Target SLA</span><strong>90%</strong></div><div class="kv"><span>Constraint</span><strong>Do not harm donor queue</strong></div><div class="kv"><span>State</span><strong>Human review required</strong></div><div class="kv"><span>Simulation model</span><strong>Erlang-C capacity proxy</strong></div><button class="primary" data-dialog="approval" style="margin-top:11px">Review simulation-only approval →</button>`)}${box('Decision rationale',`<p class="panel-sub">No intervention is endorsed automatically. Staff shortage and queueing exposure require a validated impact model, verified donor protection and owner sign-off.</p>` )}</div></div>`}
function actionsPage(d){let a=d.actions,all=d.action_log;return `<div class="two-col"><div class="stack"><div class="top-banner"><span class="critical-pill">◷ AUDIT TRAIL</span><div><h2>Actions & Approvals</h2><p>Simulated actions, approval records and follow-up outcomes. Human authorization is never inferred from a name field.</p></div><div class="banner-stat"><strong>${a.length}</strong><span>Recent records</span></div><div class="banner-impact"><strong>${a.filter(x=>String(x.approval_status).includes('PENDING')).length}</strong><span>Pending</span></div></div><div class="kpi-grid">${kpi('Recorded actions',n(a.length),'Synthetic history',[],colors.blue)}${kpi('Review required',n(a.filter(x=>x.approval_required===1).length),'Approval gated',[],colors.red)}${kpi('Simulation completed',n(a.filter(x=>String(x.execution_status).includes('COMPLETED')).length),'Historical fixture',[],colors.green)}${kpi('Activity events',n(all.length),'Recorded events',[],colors.violet)}${kpi('Auditability','100%','Every row has an action ID',[],colors.cyan)}</div>${box('Action Register',`<div class="table-wrap"><table class="mini-table"><thead><tr><th>Action ID</th><th>Type</th><th>Incident</th><th>Owner</th><th>Approval</th><th>Execution</th><th>Time</th></tr></thead><tbody>${a.map(t=>`<tr><td>${esc(t.action_id)}</td><td>${esc(labelCase(t.action_type))}</td><td>${esc(t.incident_id)}</td><td>${esc(t.owner_role||t.approved_by||'Real-Time Lead')}</td><td>${badge(t.approval_status)}</td><td>${badge(t.execution_status)}</td><td>${hh(t.action_at||t.created_at)}</td></tr>`).join('')}</tbody></table></div>`)}${box('Recorded action activity',`<div class="three-grid">${all.slice(0,9).map(x=>`<div class="list-row"><div><h3>${esc(labelCase(x.event_type))}</h3><p>${esc(x.action_id)} · ${hh(x.event_at)}</p></div></div>`).join('')}</div>`)}</div><div class="stack">${box('Actions requiring attention',`<p class="panel-sub">Operational mitigation plans requiring explicit sign-off.</p>${a.slice(0,6).map(t=>`<div class="recommend-card"><div class="panel-head"><b>${esc(labelCase(t.action_type))}</b>${badge(t.approval_status)}</div><p class="small muted">${esc(t.incident_id)} · ${esc(t.owner_role)}</p><div class="kv"><span>Execution</span><strong>${esc(labelCase(t.execution_status))}</strong></div><button class="secondary" data-dialog="action-${esc(t.action_id)}" style="margin-top:8px">Inspect record →</button></div>`).join('')}`)}${box('Integrity of outcome claims',`<div class="empty" style="text-align:left"><b>Observed ≠ caused</b><p>Historical SLA movement after an action is not evidence that the action caused improvement. Outcomes shown here retain their recorded synthetic origin.</p></div>`)}</div></div>`}
function notificationsPage(d){let ev=d.notifications;let ch={};ev.forEach(e=>ch[e.channel]=(ch[e.channel]||0)+1);return `<div class="two-col"><div class="stack"><div class="top-banner"><span class="critical-pill">✉ ESCALATION</span><div><h2>Notification intelligence</h2><p>Per-incident notification history and suppression. All deliveries below are simulated records.</p></div><div class="banner-stat"><strong>${n(ev.length)}</strong><span>Recent events</span></div><div class="banner-impact"><strong>Demo</strong><span>No real sends</span></div></div><div class="kpi-grid">${kpi('Recorded events',n(d.notification_summary.TOTAL_EVENTS||0),'Until replay time',[],colors.blue)}${kpi('Simulated sent',n(d.notification_summary.SIMULATED_SENT||0),'Not real delivery',[],colors.green)}${kpi('Simulated failed',n(d.notification_summary.SIMULATED_FAILED||0),'Delivery fixture',[],colors.red)}${kpi('Suppressed',n(d.notification_summary.SIMULATED_SUPPRESSED||0),'Deduplicated fixture',[],colors.amber)}${kpi('Channels',n(Object.keys(ch).length),'Fixture channels',[],colors.violet)}</div>${box('Event Ledger',notificationsList(d,28))}${box('Escalation rules',`<div class="table-wrap"><table class="mini-table"><thead><tr><th>Severity</th><th>Role</th><th>Channel</th><th>Delay</th><th>Ack SLA</th><th>Cooldown</th></tr></thead><tbody>${d.escalation_matrix.slice(0,18).map(x=>`<tr><td>${badge(x.severity)}</td><td>${esc(x.recipient_role)}</td><td>${esc(x.channel)}</td><td>${n(x.delay_minutes)}m</td><td>${n(x.ack_sla_minutes)}m</td><td>${n(x.dedup_cooldown_minutes)}m</td></tr>`).join('')}</tbody></table></div>`)}</div><div class="stack">${box('Notification summary',notificationCounters(d))}${box('Channel distribution',Object.entries(ch).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="kv"><span>${esc(k)}</span><strong>${n(v)} / ${n(ev.length)} events</strong></div><div class="progress"><span style="width:${ev.length?100*v/ev.length:0}%"></span></div>`).join(''))}${box('Escalation ladder',d.escalation_matrix.filter(x=>x.enabled==1).slice(0,8).map((x,i)=>`<div class="list-row"><span class="badge watch">L${i+1}</span><div style="flex:1"><h3>${esc(x.recipient_role)}</h3><p>${esc(x.channel)} · after ${n(x.delay_minutes)} min</p></div></div>`).join(''))}${box('Notification quality',`<p class="panel-sub">Every deduplicated or suppressed event must remain visible in the ledger. A delivery_attempt_at alone is not evidence a recipient received the message.</p>`)}</div></div>`}
function historical(d){let weekly=d.weekly,monthly=d.monthly,days=d.daily;let data=d.timeline;return `<div class="two-col"><div class="stack"><div class="page-title"><div><h1>Historical Analytics</h1><p>Intraday · weekly · monthly · long-range operating patterns</p></div>${badge('6-month synthetic history')}</div><div class="kpi-grid">${kpi('Weeks shown',n(weekly.length),'Comparable operating periods',[],colors.blue)}${kpi('Months shown',n(monthly.length),'Historical coverage',[],colors.blue)}${kpi('Known incidents',n(d.matches.length),'Comparable matches',[],colors.violet)}${kpi('Current SLA',percent(d.current.sla),'Selected queue',[],colors.red)}${kpi('Current AHT',n(d.current.aht)+'s','Selected interval',[],colors.amber)}</div>${box('',plot({title:'Weekly performance trends',points:weekly.map(x=>String(x.period).slice(-5)),lines:[{label:'SLA (%)',values:weekly.map(x=>x.sla*100),color:colors.blue,fill:true}],target:90,min:0,max:100,footer:'Weighted aggregate from weekly KPI fixtures.'}))}<div class="dual-grid">${box('',plot({title:'Monthly service level',points:monthly.map(x=>x.period),lines:[{label:'SLA (%)',values:monthly.map(x=>x.sla*100),color:colors.cyan,fill:true}],target:90,min:0,max:100,height:214,footer:'Six-month history'}))}${box('',plot({title:'Daily offered call volume',points:days.map(x=>String(x.date).slice(-5)),lines:[{label:'Offered calls',values:days.map(x=>x.offered_calls),color:colors.violet,fill:true}],height:214,footer:'Most recent 32 days'}))}</div>${box('Queue × hour heatmap — recent observed SLA',`<div class="heatmap"><span class="tiny muted">Queue / hour</span>${Array.from({length:24},(_,i)=>`<span class="tiny muted" style="text-align:center">${String(i).padStart(2,'0')}</span>`).join('')}${d.queue_comparison.map(q=>`<span class="heatrow-label">${esc(q.queue)}</span>${Array.from({length:24},(_,i)=>{const h=d.hourly_heatmap.find(v=>v.queue===q.queue&&v.hour===i);const v=h?.sla;const color=v==null?'#173047':v<.75?'#d63a55':v<.85?'#d1a148':v<.92?'#148e99':'#155d9f';return `<span class="heat-cell" style="background:${color}" title="${esc(q.queue)} ${i}:00 · Historical weighted SLA ${v==null?'No data':percent(v)}"></span>`}).join('')}`).join('')}</div><p class="footnote">Observed 28-day weighted SLA by queue and hour, computed only from synthetic operational records available by the selected replay time.</p>`)}${box('Historical peer review',`<div class="table-wrap"><table class="mini-table"><thead><tr><th>Period</th><th>Queue</th><th>Offered</th><th>SLA</th><th>AHT</th><th>Abandon</th></tr></thead><tbody>${monthly.slice().reverse().map(v=>`<tr><td>${esc(v.period)}</td><td>${esc(v.queue)}</td><td>${n(v.offered_calls)}</td><td>${percent(v.sla)}</td><td>${n(v.aht_seconds,0)}s</td><td>${percent(v.abandon_rate)}</td></tr>`).join('')}</tbody></table></div>`)}</div><div class="stack">${box('Past comparable incidents',d.matches.length?d.matches.map(i=>`<div class="list-row"><div><h3>${esc(i.matched_incident_id)}</h3><p>${esc(i.matched_date)} · rank ${i.rank}</p></div>${badge(i.same_queue?'Same queue':'Cross queue')}</div>`).join(''):'<div class="empty">No linked matches.</div>')}${box('Learned actions & outcomes',d.actions.slice(0,7).map(t=>`<div class="list-row"><div><h3>${esc(labelCase(t.action_type))}</h3><p>Observed change ${t.observed_change_pp!=null?n(t.observed_change_pp,1)+' pp':'not available'} · ${esc(t.incident_id)}</p></div><span class="badge neutral">Causality unproven</span></div>`).join(''))}${box('Historical evidence limitations',`<p class="panel-sub">The dataset is synthetic. Incident matching is heuristic, forecasts use an uncalibrated baseline, and before/after action changes cannot establish causal improvement.</p>` )}</div></div>`}
function asideDialog(){let key=state.dialog,d=state.data;if(!key)return '';let content='',title='Details';if(key==='ai'){title='Live Gemini integration';content='<p>Opsentia features a server-side Gemini Evidence Investigator with 10 read-only analytical tools and sanitized traces. When an API key is unconfigured, it runs a verified deterministic fallback to ensure full truthfulness.</p><button class="primary" id="btn-run-investigation" style="margin-top:10px">Run Evidence Investigation</button>'}else if(key==='approval'){title='Human approval — mitigation sign-off';let pendingAct=d.actions.find(x=>x.approval_status==='PENDING_APPROVAL'||x.approval_status==='PROPOSED')||d.actions[0];let targetActionId=pendingAct?pendingAct.action_id:'ACT-0001';let actionDesc=pendingAct?`${pendingAct.action_type} (${targetActionId})`:'Option 2: Add 8 Temporary Agents';let modeNotice=state.canMutate?'':'<p class="panel-sub" style="color:var(--amber,#e8a044);margin-bottom:8px">ℹ Public Demo: Read-only viewer session. Action mutation requires authenticated operator credentials.</p>';content=`<p>Authorize mitigation action under simulated execution. The action state machine records identity, role, timestamp, and audit trail.</p>${modeNotice}<div class="kv"><span>Authorized Role</span><strong>${state.canMutate?'Operations Director (Authenticated)':'Viewer (Read-Only Demo)'}</strong></div><div class="kv"><span>Mitigation Action</span><strong>${esc(actionDesc)}</strong></div><div class="kv"><span>Action ID</span><strong>${esc(targetActionId)}</strong></div><button class="primary" id="btn-submit-approval" data-action-id="${esc(targetActionId)}" style="margin-top:14px">${state.canMutate?'Approve Mitigation Plan (Simulated)':'Simulate Approval (Read-Only Demo)'}</button>`}else if(key.startsWith('scenario-')){let v=d.scenarios.find(x=>x.scenario_id===key.slice(9));title='Scenario simulation';content=v?Object.entries(v).map(([k,v])=>`<div class="kv"><span>${esc(labelCase(k))}</span><strong>${esc(v)}</strong></div>`).join('')+`<button class="primary" style="margin-top:12px" data-simulate-id="${esc(v.scenario_id)}">Run Erlang-C Capacity Simulation</button>`:'Scenario not available'}else if(key.startsWith('doc-')){let v=d.knowledge.find(x=>x.document_id===key.slice(4));title=v?.title||'Knowledge source';content=v?`<p>${esc(v.content_text)}</p><div class="kv"><span>Document owner</span><strong>${esc(v.owner_role)}</strong></div><div class="kv"><span>Approval status</span><strong>${esc(v.approval_status)}</strong></div>`:'No document'}else if(key.startsWith('action-')){let v=d.actions.find(x=>x.action_id===key.slice(7));title=v?.action_type||'Action';content=v?Object.entries(v).map(([k,v])=>`<div class="kv"><span>${esc(labelCase(k))}</span><strong>${esc(v)}</strong></div>`).join(''):'No action'}else{title='Details';content='<p>More information is not available for this selection.</p>'}return `<div class="drawer-bg" data-dialog-close="1"><div class="drawer" role="dialog" aria-modal="true"><div class="panel-head"><h2>${esc(title)}</h2><button class="secondary" data-dialog-close="1">Close ✕</button></div>${content}</div></div>`}
function nav(){return `<aside class="sidebar"><div class="brand"><img src="/assets/opsentia.svg" alt="Opsentia — Intelligence That Anticipates."/></div><nav class="nav" aria-label="Main navigation">${pages.map(([id,t,ico])=>`<button class="nav-btn ${state.page===id?'active':''}" data-page="${id}">${icon(ico)}${esc(t)}${state.page===id?'<i class="nav-dot"></i>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><img src="/assets/vyra.png" alt="Team VYRA"/><span>Built by Team VYRA<br/>Future of Work</span></div></aside>`}
function topbar(d){return `<header class="topbar"><div class="search">${icon('search')}<input id="global-search" placeholder="Search queues, screens, incidents…" value="${esc(state.search)}" aria-label="Global search"/></div><div class="top-spacer"></div><select class="header-select" id="queue-filter" aria-label="Choose queue">${d.meta.queues.map(q=>`<option ${q===state.queue?'selected':''}>${esc(q)}</option>`).join('')}</select><input id="date-filter" class="header-select" type="date" value="${day(at())}" min="2026-03-16" max="2026-09-13" title="Replay date"/><select class="header-select" id="time-filter" title="Replay time">${Array.from({length:48},(_,i)=>{const hhmm=String(Math.floor(i/2)).padStart(2,'0')+':'+(i%2?'30':'00');return `<option value="${hhmm}" ${hh(at())===hhmm?'selected':''}>${hhmm}</option>`}).join('')}</select><button class="secondary" id="btn-step-replay" style="margin-left:6px;font-size:12px;padding:6px 10px" title="Step forward 30 minutes in replay">Step +30m →</button><div class="status" title="Fixture replay, not a live feed"><span class="led"></span><div class="clock"><b>Replay · ${hh(at())}</b><span class="date">${day(at())} · synthetic</span></div></div><button class="header-icon" data-dialog="ai" aria-label="Gemini status">${icon('spark')}</button><span class="badge ${d.meta.gemini_verified?'good':'neutral'}">${d.meta.gemini_verified?'AI verified':'AI fallback'}</span><span class="avatar">VY</span></header>`}
function render(){let d=state.data;if(!d){$('#app').innerHTML='<div class="loading">Loading dataset-backed dashboard…</div>';return}let renderFn={live,metrics:allMetrics,investigation,decision,actions:actionsPage,notifications:notificationsPage,historical}[state.page]||live;$('#app').innerHTML=`<div class="app">${nav()}<div class="viewport">${topbar(d)}<main class="page" id="page"><div style="margin-bottom:9px" class="tag-row"><span class="badge neutral">SYNTHETIC DATA / REPLAY</span><span class="badge neutral">26-CSV fixture pack</span><span class="badge ${d.meta.gemini_verified?'good':'neutral'}">${d.meta.gemini_verified?'Gemini Live Verified':'Deterministic Fallback'}</span></div>${renderFn(d)}<div class="footnote">Opsentia by VYRA · Source: synthetic_operations.csv + linked fixtures · Predictions are uncalibrated estimates · No real notifications or business actions executed.</div></main></div></div>${asideDialog()}${chatWidget(d)}`}
let noticeTimer=0;function toast(t){document.querySelector('.toast')?.remove();let el=document.createElement('div');el.className='toast';el.textContent=t;document.body.appendChild(el);clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>el.remove(),3700)}
async function load(){state.loading=true;if(!state.sessionToken){try{let sRes=await fetch('/api/auth/demo-session');if(sRes.ok){let sData=await sRes.json();state.sessionToken=sData.session_token;state.canMutate=sData.can_mutate}}catch(_e){}}let url=`/api/ui/bootstrap?queue=${encodeURIComponent(state.queue)}&as_of=${encodeURIComponent(state.asOf)}`;try{let r=await fetch(url);if(!r.ok){const err=await r.text();throw new Error(err.slice(0,180))}state.data=await r.json();render()}catch(e){console.error(e);$('#app').innerHTML=`<div class="loading"><h2>Unable to load Opsentia data</h2><p>${esc(e.message)}</p><p>Start the API with <code>uvicorn backend.app:app --reload --port 8080</code> and open http://localhost:8080</p></div>`}finally{state.loading=false}}
function setTime(){state.investigation=null;let date=$('#date-filter')?.value||day(at()),time=$('#time-filter')?.value||hh(at());state.asOf=`${date} ${time}:00`;load()}
document.addEventListener('click',async e=>{let tChat=e.target.closest('#btn-toggle-chat');if(tChat){state.chatOpen=!state.chatOpen;render();if(state.chatOpen)scrollChatToBottom();return}let cChat=e.target.closest('#btn-chat-close');if(cChat){state.chatOpen=false;render();return}let cPill=e.target.closest('.chat-pill');if(cPill){let p=cPill.dataset.prompt;if(p)sendChatMessage(p);return}let hBtn=e.target.closest('[data-horizon]');if(hBtn){let h=hBtn.dataset.horizon;if(h){state.metricsHorizon=h;render()}return}let stepBtn=e.target.closest('#btn-step-replay');if(stepBtn){try{stepBtn.disabled=true;stepBtn.textContent='Stepping…';let r=await fetch('/api/coil/replay/advance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({current_as_of:state.asOf,minutes:30})});if(r.ok){let res=await r.json();state.asOf=res.new_as_of;state.investigation=null;toast(`Replay advanced to ${res.new_as_of.slice(11,16)} (${res.incident_state.severity} severity)`);await load()}}catch(err){toast('Failed to step replay')}finally{stepBtn.disabled=false;stepBtn.textContent='Step +30m →'}return}let runInv=e.target.closest('#btn-run-investigation');if(runInv){try{runInv.disabled=true;runInv.textContent='Running AI tools…';let r=await fetch('/api/investigate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({incident_id:selected()?.id||'EV-2026-0913-01',queue:state.queue,as_of:at()})});if(r.ok){state.investigation=await r.json();state.page='investigation';state.dialog=null;toast(`Investigation complete (${state.investigation.tool_calls.length} tools executed)`);render()}}catch(err){toast('Investigation error: '+err.message)}finally{runInv.disabled=false;runInv.textContent='✦ Run Investigation (Gemini / COIL)'}return}let appBtn=e.target.closest('#btn-submit-approval');if(appBtn){try{let actionId=appBtn.dataset.actionId||'ACT-0001';appBtn.disabled=true;appBtn.textContent='Authorizing…';let appHeaders={'Content-Type':'application/json'};if(state.sessionToken){appHeaders['Authorization']=`Bearer ${state.sessionToken}`}let r=await fetch(`/api/decisions/${encodeURIComponent(actionId)}/approve`,{method:'POST',headers:appHeaders,body:JSON.stringify({actor:'Lead Operations Director',role:'Operations Director',as_of:at(),rationale:'Approved mitigation plan under simulated execution'})});if(r.ok){toast(`Mitigation action ${actionId} authorized by Operations Director!`);state.dialog=null;await load()}else if(r.status===409){toast(`Action ${actionId} is already approved or not in pending state (HTTP 409 Conflict).`)}else if(r.status===403){let errData=await r.json().catch(()=>({}));toast(`Approval blocked (HTTP 403 Read-Only): ${errData.detail||'Mutations require authenticated operator credentials.'}`)}else{let errData=await r.json().catch(()=>({}));toast(`Approval failed (${r.status}): ${errData.detail||'Unauthorized'}`)}}catch(err){toast('Approval error: '+err.message)}finally{appBtn.disabled=false;appBtn.textContent='Approve Mitigation Plan (Simulated)'}return}let simBtn=e.target.closest('[data-simulate-id]');if(simBtn){try{let scenarioId=simBtn.dataset.simulateId;let sc=state.data?.scenarios?.find(x=>x.scenario_id===scenarioId)||{};simBtn.disabled=true;simBtn.textContent='Simulating…';let r=await fetch('/api/simulations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({queue:sc.target_queue||state.queue,as_of:at(),scenario_type:sc.scenario_type||'add_temporary_agents',agents_to_add:Number(sc.agents_to_add||0),agents_to_transfer:Number(sc.agents_to_transfer||0),donor_queue:sc.donor_queue||null,duration_hours:Number(sc.duration_hours||4.0),hourly_rate_usd:Number(sc.hourly_rate_usd||45.0),target_sla:0.90})});if(r.ok){let res=await r.json();let warn=res.prediction_status==='UNVALIDATED_STEADY_STATE_PROXY'?' (Unvalidated Steady-State Proxy)':'';toast(`Simulated ${labelCase(res.scenario_type)}: Modeled SLA ${res.projected_sla_pct}%${warn} · Cost: $${res.estimated_cost_usd}`);state.dialog=null;await load()}}catch(err){toast('Simulation error')}return}let navbtn=e.target.closest('[data-page]');if(navbtn){state.page=navbtn.dataset.page;if(navbtn.dataset.queue){state.queue=navbtn.dataset.queue;state.investigation=null}state.dialog=null;state.search='';if(navbtn.dataset.queue)load();else render();window.scrollTo({top:0,behavior:'smooth'});return}let dg=e.target.closest('[data-dialog]');if(dg){state.dialog=dg.dataset.dialog;render();return}if(e.target.closest('[data-dialog-close]')){state.dialog=null;render();return}})
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();let input=$('#chat-input-field');sendChatMessage(input?.value)}})
document.addEventListener('input',e=>{if(e.target.id==='chat-input-field')state.chatInput=e.target.value})
document.addEventListener('change',e=>{if(e.target.id==='queue-filter'){state.investigation=null;state.queue=e.target.value;load()}if(e.target.id==='date-filter'||e.target.id==='time-filter')setTime()})
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(state.dialog||state.chatOpen)){if(state.dialog)state.dialog=null;else state.chatOpen=false;render();return}if(e.key==='Enter'&&e.target.id==='global-search'){let v=e.target.value.trim().toLowerCase();let page=pages.find(p=>p[1].toLowerCase().includes(v));if(page){state.page=page[0];render()}else{let q=state.data.meta.queues.find(q=>q.toLowerCase().includes(v));if(q){state.queue=q;load()}else toast('No matching page or queue found.')}}})
load();
